        @Index(name = "idx_product_date", columnList = "release_date"),                 // 출시일 정렬
        @Index(name = "idx_product_brand_category", columnList = "brand_id, category_id"), // 복합 인덱스 (브랜드+카테고리)
        @Index(name = "idx_product_name", columnList = "name"),                         // 상품명 검색
