   102	    /**
   103	     * 웹소켓 핸드셰이크 후 실행되는 메소드
   104	     *
   105	     * @param request 서버 HTTP 요청
   106	     * @param response 서버 HTTP 응답
   107	     * @param wsHandler 웹소켓 핸들러
   108	     * @param exception 발생한 예외 (있는 경우)
   109	     */
   110	    @Override
   111	    public void afterHandshake(
   112	            ServerHttpRequest request,
   113	            ServerHttpResponse response,
   114	            WebSocketHandler wsHandler,
   115	            Exception exception) {
   117	        String uri = request.getURI().toString();
   118	        String ip = request.getRemoteAddress() != null ? request.getRemoteAddress().toString() : "알 수 없음";
   120	        if (exception != null) {
   121	            log.error("웹소켓 연결 실패: 요청 경로={}, 요청 IP={}, 원인={}", uri, ip, exception.getMessage(), exception);
   122	            return;
   123	        }
   125	        // 명시적으로 attributes를 Map으로 변환
   126	        if (request instanceof ServletServerHttpRequest) {
   127	            ServletServerHttpRequest servletRequest = (ServletServerHttpRequest) request;
   128	            Object attributeObject = servletRequest.getServletRequest().getAttribute("attributes");
   130	            if (attributeObject instanceof Map) {
   131	                @SuppressWarnings("unchecked")
   132	                Map<String, Object> attributes = (Map<String, Object>) attributeObject;
   134	                if (attributes.containsKey("email")) {
   135	                    String email = (String) attributes.get("email");
   137	                    String redisKey = "WebSocket:User:" + email;
   139	                    Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS); // TTL 확인
   140	                    if (remainingTime == null || remainingTime <= 600) { // 10분 이하이거나 없을 때 갱신
   141	                        redisTemplate.opsForValue().set(redisKey, "CONNECTED");
   142	                        redisTemplate.expire(redisKey, 30, TimeUnit.MINUTES);
   143	                        log.info("Redis TTL 갱신: 사용자 Email={}, 남은 TTL={}초", email, remainingTime);
   144	                    }
   146	                    log.info("웹소켓 연결 성공: 사용자 Email={}, IP={}", email, ip);
   147	                } else {
   148	                    log.warn("웹소켓 연결 성공했으나 'email'이 attributes에 없음 (IP={})", ip);
   149	                }
   150	            } else {
   151	                log.error("웹소켓 연결 성공했으나 attributes가 Map 타입이 아님 (IP={})", ip);
   152	            }
   153	        } else {
   154	            log.error("웹소켓 요청이 ServletServerHttpRequest 타입이 아님 (IP={})", ip);
   155	        }
   156	    }
   158	    /**
   159	     * 요청에서 액세스 토큰 추출
   160	     *
   161	     * @param request 서버 HTTP 요청
   162	     * @return 추출된 액세스 토큰 또는 null
   163	     */
   164	    private String extractAccessToken(ServerHttpRequest request) {
   165	        if (request instanceof ServletServerHttpRequest) {
   166	            HttpServletRequest servletRequest = ((ServletServerHttpRequest) request).getServletRequest();
   168	            Cookie[] cookies = servletRequest.getCookies();
   169	            if (cookies != null) {
   170	                for (Cookie cookie : cookies) {
   171	                    if ("ACCESS_TOKEN".equals(cookie.getName())) {
   172	                        return cookie.getValue();
   173	                    }
   174	                }
   175	            }
   176	        }
   178	        return null;
   179	    }
