 112	@RestController
 113	@RequestMapping("/access-log/commands")
 114	@RequiredArgsConstructor
 115	@Slf4j
 116	public class UserAccessLogCommandController {
 117	
 118	    private final UserAccessLogCommandService userAccessLogCommandService;
 119	    // 정규식 패턴: IPv4 주소 검증용
 120	    private static final Pattern ipPattern = Pattern.compile(
 121	            "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$");
 122	
 123	    /**
 124	     * 접근 로그 생성 엔드포인트
 125	     * @param logDto 접근 로그 정보
 126	     * @param request HttpServletRequest (IP, User-Agent, Referer 등 추출)
 127	     * @return 성공 시 204 No Content
 128	     * @throws InvalidParameterException 유효하지 않은 파라미터인 경우
 129	     */
 130	    @PostMapping("/create")
 131	    public ResponseEntity<Void> createAccessLog(@RequestBody UserAccessLogDto logDto, HttpServletRequest request) {
 132	        if (logDto == null) {
 133	            throw new InvalidParameterException(AccessLogErrorCode.INVALID_ACCESS_LOG_DATA,
 134	                    "접근 로그 데이터가 누락되었습니다.");
 135	        }
 136	
 137	        enrichAccessLogWithRequestData(logDto, request);
 138	        userAccessLogCommandService.createAccessLog(logDto);
 139	        return ResponseEntity.noContent().build();
 140	    }
 141	
 142	    /**
 143	     * 요청 정보를 이용해 DTO 데이터 보강
 144	     */
 145	    private void enrichAccessLogWithRequestData(UserAccessLogDto logDto, HttpServletRequest request) {
 146	        // IP 주소 처리
 147	        String clientIp = extractClientIp(request);
 148	        logDto.setIpAddress(clientIp);
 149	
 150	        // User-Agent 처리
 151	        String userAgent = request.getHeader("User-Agent");
 152	        logDto.setUserAgent(userAgent);
 153	
 154	        // Referer URL 처리
 155	        String refererUrl = request.getHeader("Referer");
 156	        logDto.setRefererUrl(refererUrl);
 157	
 158	        // 이메일이 없으면 익명 사용자 처리
 159	        if (logDto.getEmail() == null || logDto.getEmail().isEmpty()) {
 160	            logDto.setEmail("Anonymous");
 161	            logDto.setAnonymous(true);
 162	        }
 163	    }
 164	
 165	    /**
 166	     * 클라이언트 IP를 추출 및 검증
 167	     */
 168	    private String extractClientIp(HttpServletRequest request) {
 169	        String clientIp = request.getHeader("X-Forwarded-For");
 170	        if (clientIp == null || clientIp.isEmpty() || "unknown".equalsIgnoreCase(clientIp)) {
 171	            clientIp = request.getHeader("Proxy-Client-IP");
 172	        }
 173	        if (clientIp == null || clientIp.isEmpty() || "unknown".equalsIgnoreCase(clientIp)) {
 174	            clientIp = request.getHeader("WL-Proxy-Client-IP");
 175	        }
 176	        if (clientIp == null || clientIp.isEmpty() || "unknown".equalsIgnoreCase(clientIp)) {
 177	            clientIp = request.getHeader("HTTP_CLIENT_IP");
 178	        }
 179	        if (clientIp == null || clientIp.isEmpty() || "unknown".equalsIgnoreCase(clientIp)) {
 180	            clientIp = request.getHeader("HTTP_X_FORWARDED_FOR");
 181	        }
 182	        if (clientIp == null || clientIp.isEmpty() || "unknown".equalsIgnoreCase(clientIp)) {
 183	            clientIp = request.getRemoteAddr();
 184	        }
 185	
 186	        // X-Forwarded-For에 여러 IP가 있을 경우 첫 번째 IP만 사용
 187	        if (clientIp != null && clientIp.contains(",")) {
 188	            clientIp = clientIp.split(",")[0].trim();
 189	        }
 190	
 191	        // IP 보안 강화: 특수 문자 제거 (XSS 방지)
 192	        if (clientIp != null) {
 193	            clientIp = clientIp.replaceAll("[^0-9.]", "");
 194	        }
 195	
 196	        // 유효한 IPv4 형식인지 검증
 197	        if (clientIp == null || clientIp.isEmpty() || !ipPattern.matcher(clientIp).matches()) {
 198	            log.warn("유효하지 않은 IP 형식: {}", clientIp);
 199	            clientIp = "0.0.0.0";
 200	        }
 201	
 202	        return clientIp;
 203	    }
