203	public class UserAccessLogProducer {
204	
205	    private static final String TOPIC_NAME = "user-access-log-topic";
206	    private final KafkaTemplate<String, UserAccessLogEvent> kafkaTemplate;
207	
208	    /**
209	     * 접근 로그를 Kafka로 전송
210	     *
211	     * @param dto 접근 로그 DTO
212	     * @throws AccessLogKafkaException Kafka 전송 실패 시
213	     */
214	    @AccessLogExceptionHandler(
215	            defaultType = AccessLogExceptionHandler.ExceptionType.KAFKA,
216	            message = "Kafka 메시지 전송 중 오류가 발생했습니다",
217	            retry = true,
218	            retryCount = 3,
219	            logLevel = AccessLogExceptionHandler.LogLevel.ERROR
220	    )
221	    @AccessLogMethodLogger(
222	            level = AccessLogMethodLogger.LogLevel.INFO,
223	            logParameters = true,
224	            logReturnValue = false,
225	            measureExecutionTime = true,
226	            customMessage = "Kafka 접근 로그 이벤트 전송"
227	    )
228	    @AccessLogPerformanceMonitor(
229	            thresholdMs = 1000L,
230	            measureMemory = false,
231	            collectMetrics = true,
232	            slowQueryThresholdMs = 3000L,
233	            enablePerformanceGrading = true,
234	            logPerformance = false
235	    )
236	    public void sendAccessLog(UserAccessLogDto dto) {
237	        try {
238	            // DTO를 이벤트로 변환 (추가된 메서드 활용)
239	            UserAccessLogEvent event = dto.toEvent();
240	
241	            // 비동기 전송 및 콜백 처리
242	            CompletableFuture<SendResult<String, UserAccessLogEvent>> future =
243	                    kafkaTemplate.send(TOPIC_NAME, event);
244	
245	            future.whenComplete((result, ex) -> {
246	                if (ex != null) {
247	                    log.error("Kafka 메시지 전송 실패: {}", dto, ex);
248	                    // 실패 처리 로직 (재시도, 알림 등)
249	                } else {
250	                    log.debug("Kafka 메시지 전송 성공: topic={}, partition={}, offset={}",
251	                            result.getRecordMetadata().topic(),
252	                            result.getRecordMetadata().partition(),
253	                            result.getRecordMetadata().offset());
254	                }
255	            });
256	        } catch (Exception e) {
257	            log.error("Kafka 메시지 준비 중 오류 발생", e);
258	            throw new AccessLogKafkaException(AccessLogErrorCode.KAFKA_SEND_ERROR,
259	                    "접근 로그를 전송하는 중 오류가 발생했습니다.", e);
260	        }
261	    }
