431	     */
432	    public GeoIPService() {
433	        try {
434	            // (1) ClassPathResource로 mmdb 파일을 가져옴
435	            ClassPathResource resource = new ClassPathResource("GeoLite2-City.mmdb");
436	
437	            // (2) InputStream 으로 DatabaseReader 생성
438	            try (InputStream inputStream = resource.getInputStream()) {
439	                this.databaseReader = new DatabaseReader.Builder(inputStream).build();
440	            }
441	        } catch (IOException e) {
442	            log.error("GeoIP 데이터베이스 초기화 실패", e);
443	            throw new GeoIPException(AccessLogErrorCode.GEO_IP_DATABASE_ERROR,
444	                    "GeoIP 데이터베이스를 초기화하는 중 오류가 발생했습니다.", e);
445	        }
446	    }
447	
448	    /**
449	     * IP 주소로부터 위치 정보를 조회합니다.
450	     *
451	     * @param ip IP 주소
452	     * @return 위치 정보 (국가, 지역, 도시)
453	     */
454	    @AccessLogExceptionHandler(
455	            defaultType = AccessLogExceptionHandler.ExceptionType.GEO_IP,
456	            message = "IP 위치 정보 조회 중 오류가 발생했습니다",
457	            retry = true,
458	            retryCount = 2,
459	            logLevel = AccessLogExceptionHandler.LogLevel.WARN
460	    )
461	    @AccessLogMethodLogger(
462	            level = AccessLogMethodLogger.LogLevel.DEBUG,
463	            logParameters = true,
464	            logReturnValue = false,
465	            measureExecutionTime = true,
466	            customMessage = "IP 주소 위치 정보 조회"
