473	            logPerformance = false
474	    )
475	    public Location getLocation(String ip) {
476	        if (ip == null || ip.isEmpty() || "localhost".equals(ip) || "127.0.0.1".equals(ip) || "0:0:0:0:0:0:0:1".equals(ip)) {
477	            // 로컬 주소이거나 IP가 없는 경우
478	            return new Location("Unknown", "Unknown", "Unknown");
479	        }
480	
481	        try {
482	            InetAddress ipAddress = InetAddress.getByName(ip);
483	            CityResponse response = databaseReader.city(ipAddress);
484	
485	            Country country = response.getCountry();
486	            Subdivision subdivision = response.getMostSpecificSubdivision();
487	            City city = response.getCity();
488	
489	            return new Location(
490	                    country != null ? country.getName() : "Unknown",
491	                    subdivision != null ? subdivision.getName() : "Unknown",
492	                    city != null ? city.getName() : "Unknown"
493	            );
494	        } catch (UnknownHostException e) {
