@RestController
@RequiredArgsConstructor
@RequestMapping("/events")
@Slf4j
public class EventQueryController {

    private final EventQueryService eventQueryService;
    private final FileUtils fileUtils;
    private static final String BASE_DIR = "/home/ubuntu/fream";
//    private static final String BASE_DIR = "C:/Users/pickj/webserver/dockerVolums/fream";

    /**
     * 모든 이벤트 목록 조회 (페이징)
     * GET /events/page
     */
    @GetMapping("/page")
    public ResponseEntity<Page<EventListDto>> getAllEventsPaging(
            @PageableDefault(size = 10, sort = "id", direction = Sort.Direction.DESC) Pageable pageable
    ) {
        log.debug("모든 이벤트 목록 페이징 조회: {}", pageable);
        return ResponseEntity.ok(eventQueryService.findAllEventsWithPaging(pageable));
    }

    /**
     * 이벤트 검색 (페이징)
     * GET /events/search
     */
    @GetMapping("/search")
    public ResponseEntity<Page<EventListDto>> searchEvents(
            @RequestParam(required = false) String keyword,
            @RequestParam(required = false) Long brandId,
            @RequestParam(required = false) Boolean isActive,
            @RequestParam(required = false) EventStatus status,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) LocalDateTime startDate,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) LocalDateTime endDate,
            @PageableDefault(size = 10, sort = "id", direction = Sort.Direction.DESC) Pageable pageable
    ) {
        log.debug("이벤트 검색: keyword={}, brandId={}, isActive={}, status={}", keyword, brandId, isActive, status);

        EventSearchCondition condition = EventSearchCondition.builder()
                .keyword(keyword)
                .brandId(brandId)
                .isActive(isActive)
                .status(status)
                .startDate(startDate)
                .endDate(endDate)
                .build();

        return ResponseEntity.ok(eventQueryService.searchEvents(condition, pageable));
    }

    /**
     * 활성 이벤트 목록 조회 (페이징)
     * GET /events/active
     */
    @GetMapping("/active")
    public ResponseEntity<Page<EventListDto>> getActiveEvents(
            @PageableDefault(size = 10, sort = "startDate", direction = Sort.Direction.DESC) Pageable pageable
    ) {
        log.debug("활성 이벤트 목록 페이징 조회");
        return ResponseEntity.ok(eventQueryService.findActiveEventsWithPaging(pageable));
    }

    /**
     * 상태별 이벤트 목록 조회
     * GET /events/status/{status}
     */
    @GetMapping("/status/{status}")
    public ResponseEntity<List<EventListDto>> getEventsByStatus(@PathVariable EventStatus status) {
        log.debug("상태별 이벤트 목록 조회: status={}", status);
        return ResponseEntity.ok(eventQueryService.findEventsByStatus(status));
    }

    /**
     * 모든 이벤트 목록 조회
     * GET /events
     */
    @GetMapping
    public ResponseEntity<List<EventListDto>> getAllEvents() {
        log.debug("모든 이벤트 목록 조회");
        return ResponseEntity.ok(eventQueryService.findAllEvents());
    }

    /**
     * 특정 브랜드의 이벤트 목록 조회
     * GET /events/brands/{brandId}
     */
    @GetMapping("/brands/{brandId}")
    public ResponseEntity<List<EventListDto>> getEventsByBrand(@PathVariable Long brandId) {
        log.debug("브랜드별 이벤트 목록 조회: brandId={}", brandId);
        return ResponseEntity.ok(eventQueryService.findEventsByBrandId(brandId));
    }

    /**
     * 이벤트 상세 정보 조회
     * GET /events/{eventId}
     */
    @GetMapping("/{eventId}")
    public ResponseEntity<EventDetailDto> getEventDetail(@PathVariable Long eventId) {
        log.debug("이벤트 상세 정보 조회: eventId={}", eventId);
        EventDetailDto eventDetail = eventQueryService.findEventById(eventId);
        log.debug("이벤트 상태: {}", eventDetail.getStatus());
        return ResponseEntity.ok(eventDetail);
    }

    /**
     * 서버 내부에 저장된 파일을 직접 읽어서 ResponseEntity<Resource>로 응답
     * GET /events/{eventId}/images/{fileName}
     */
    @GetMapping("/{eventId}/images/{fileName}")
    public ResponseEntity<?> getEventImage(
            @PathVariable("eventId") Long eventId,
            @PathVariable("fileName") String fileName
    ) {
        log.debug("이벤트 이미지 조회: eventId={}, fileName={}", eventId, fileName);

        // 디렉토리 + 파일명
        String directory = "event/" + eventId;

        // FileUtils를 사용해 파일 존재 확인
        if (!fileUtils.existsFile(directory, fileName)) {
            log.warn("이벤트 이미지 파일을 찾을 수 없음: eventId={}, fileName={}", eventId, fileName);
            return ResponseEntity.notFound().build();
        }

        // 파일 경로 생성
//        File file = new File(BASE_DIR + File.separator + directory + File.separator + fileName);
        File file = new File(BASE_DIR + "/" + directory + "/" + fileName);

        // 파일 확장자에 따라 ContentType 설정
        HttpHeaders headers = new HttpHeaders();
        if (fileName.toLowerCase().endsWith(".jpg") || fileName.toLowerCase().endsWith(".jpeg")) {
            headers.setContentType(MediaType.IMAGE_JPEG);
        } else if (fileName.toLowerCase().endsWith(".png")) {
            headers.setContentType(MediaType.IMAGE_PNG);
        } else if (fileName.toLowerCase().endsWith(".gif")) {
            headers.setContentType(MediaType.IMAGE_GIF);
        } else {
            headers.setContentType(MediaType.APPLICATION_OCTET_STREAM);
        }

        Resource resource = new FileSystemResource(file);
        return ResponseEntity.ok()
                .headers(headers)
                .body(resource);
    }
}package com.fream.back.domain.event.scheduler;

import com.fream.back.domain.event.entity.Event;
import com.fream.back.domain.event.repository.EventRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 이벤트 상태 자동 업데이트 스케줄러
 * - UPCOMING -> ACTIVE, ACTIVE -> ENDED 상태 변환을 주기적으로 체크
 */
@Component
@RequiredArgsConstructor
@Slf4j
@EnableScheduling  // 스케줄링 기능 활성화
public class EventStatusScheduler {

    private final EventRepository eventRepository;

    /**
     * 1시간마다 실행되는 이벤트 상태 체크 스케줄러
     * - UPCOMING 상태의 이벤트 중 시작 시간이 지난 이벤트를 체크
     * - ACTIVE 상태의 이벤트 중 종료 시간이 지난 이벤트를 체크
     *
     * cron = "0 0 * * * *": 매시 정각마다 실행 (초 분 시 일 월 요일)
     */
    @Scheduled(cron = "0 0 * * * *")
    @Transactional
    public void checkEventStatus() {
        log.info("이벤트 상태 체크 스케줄러 실행 시작: {}", LocalDateTime.now());

        LocalDateTime now = LocalDateTime.now();

        // 1. 예정된 이벤트(UPCOMING) 중 시작 시간이 지난 이벤트를 ACTIVE로 업데이트
        checkUpcomingToActiveEvents(now);

        // 2. 활성 이벤트(ACTIVE) 중 종료 시간이 지난 이벤트를 ENDED 상태로 처리
        checkActiveToEndedEvents(now);

        log.info("이벤트 상태 체크 스케줄러 실행 완료: {}", LocalDateTime.now());
    }

    /**
     * UPCOMING -> ACTIVE 상태 변경 체크
     */
    private void checkUpcomingToActiveEvents(LocalDateTime now) {
        try {
            // 예정된 이벤트 중 시작 시간이 현재 이전인 이벤트 조회
            // (시작일 <= 현재) AND (종료일 > 현재)의 조건으로 시작 시간이 지났으나 종료되지 않은 이벤트 조회
            List<Event> startedEvents = eventRepository.findByStartDateBeforeAndEndDateAfter(now, now);

            int count = 0;
            for (Event event : startedEvents) {
                if (event.isUpcoming()) {  // 현재 UPCOMING 상태인 이벤트만 처리
                    // 이벤트 엔티티에 상태 변경 처리 로직이 있다면 호출
                    // (현재는 isActive(), isUpcoming() 등의 메서드만 있으므로 로그만 남김)
                    log.info("이벤트 상태 변경: UPCOMING -> ACTIVE, eventId={}, title={}",
                            event.getId(), event.getTitle());
                    count++;
                }
            }

            if (count > 0) {
                log.info("UPCOMING -> ACTIVE 상태로 변경된 이벤트 수: {}", count);
            } else {
                log.debug("UPCOMING -> ACTIVE 상태로 변경된 이벤트 없음");
            }
        } catch (Exception e) {
            log.error("UPCOMING -> ACTIVE 상태 변경 처리 중 오류 발생", e);
        }
    }

    /**
     * ACTIVE -> ENDED 상태 변경 체크
     */
    private void checkActiveToEndedEvents(LocalDateTime now) {
        try {
            // 종료 시간이 지난 이벤트 조회 (현재 >= 종료일)
            List<Event> endedEvents = eventRepository.findByEndDateLessThanEqual(now);

            int count = 0;
            for (Event event : endedEvents) {
                if (event.isActive()) {  // 현재 ACTIVE 상태인 이벤트만 처리
                    // 이벤트 엔티티에 상태 변경 처리 로직이 있다면 호출
                    // (현재는 isEnded() 등의 메서드만 있으므로 로그만 남김)
                    log.info("이벤트 상태 변경: ACTIVE -> ENDED, eventId={}, title={}",
                            event.getId(), event.getTitle());
                    count++;
                }
            }

            if (count > 0) {
                log.info("ACTIVE -> ENDED 상태로 변경된 이벤트 수: {}", count);
            } else {
                log.debug("ACTIVE -> ENDED 상태로 변경된 이벤트 없음");
            }
        } catch (Exception e) {
            log.error("ACTIVE -> ENDED 상태 변경 처리 중 오류 발생", e);
        }
    }
}

