    30	                Join<UserSanction, User> userJoin = root.join("user");
    31	                predicates.add(criteriaBuilder.like(userJoin.get("email"), "%" + searchDto.getEmail() + "%"));
    32	            }
    34	            // Status 조건
    35	            if (searchDto.getStatus() != null) {
    36	                predicates.add(criteriaBuilder.equal(root.get("status"), searchDto.getStatus()));
    37	            }
    39	            // Type 조건
    40	            if (searchDto.getType() != null) {
    41	                predicates.add(criteriaBuilder.equal(root.get("type"), searchDto.getType()));
    42	            }
    44	            // Start date range 조건
    45	            if (searchDto.getStartDateStart() != null) {
    46	                predicates.add(criteriaBuilder.greaterThanOrEqualTo(root.get("startDate"), searchDto.getStartDateStart()));
    47	            }
    48	            if (searchDto.getStartDateEnd() != null) {
    49	                predicates.add(criteriaBuilder.lessThanOrEqualTo(root.get("startDate"), searchDto.getStartDateEnd()));
    50	            }
    52	            // End date range 조건
    53	            if (searchDto.getEndDateStart() != null) {
    54	                predicates.add(criteriaBuilder.greaterThanOrEqualTo(root.get("endDate"), searchDto.getEndDateStart()));
    55	            }
    56	            if (searchDto.getEndDateEnd() != null) {
    57	                predicates.add(criteriaBuilder.lessThanOrEqualTo(root.get("endDate"), searchDto.getEndDateEnd()));
    58	            }
    60	            // Created date range 조건
    61	            if (searchDto.getCreatedDateStart() != null) {
    62	                predicates.add(criteriaBuilder.greaterThanOrEqualTo(root.get("createdDate"), searchDto.getCreatedDateStart()));
