    64	            if (searchDto.getCreatedDateEnd() != null) {
    65	                predicates.add(criteriaBuilder.lessThanOrEqualTo(root.get("createdDate"), searchDto.getCreatedDateEnd()));
    66	            }
    68	            return criteriaBuilder.and(predicates.toArray(new Predicate[0]));
    69	        };
