        FILE_SIZE_LIMIT,            // 파일 크기 제한
        CREATION_FREQUENCY,         // 생성 빈도 제한
        BRAND_STATUS_CHECK,         // 브랜드 상태 확인
        AUTO_ARCHIVE_RULE           // 자동 아카이빙 규칙
    }
    enum BrandDeactivationAction {
        MARK_INACTIVE,      // 이벤트를 비활성으로 표시
