    enum RuleViolationAction {
        THROW_EXCEPTION,    // 예외 발생
        LOG_AND_ALLOW,      // 로그 남기고 허용
        MODIFY_REQUEST,     // 요청 수정
        PROMPT_APPROVAL     // 승인 요청
    }
}
