 36	        try {
 37	            // 현재 시각
 38	            LocalDateTime now = LocalDateTime.now();
 39	            // 검색 범위: [now-1h, now+1h]
 40	            LocalDateTime startTime = now.minusHours(1);
 41	            LocalDateTime endTime = now.plusHours(1);
 42	
 43	            // 해당 범위의 날씨 데이터 목록 조회
