 52	            // 최솟값(가장 가까운 시차)을 찾음
 53	            WeatherData closest = weatherDataList.stream()
 54	                    .min(Comparator.comparingLong(w ->
 55	                            Math.abs(Duration.between(w.getTimestamp(), now).toMillis())))
 56	                    .orElse(null);
