232	    private void validateStatusTransition(WarehouseStatus currentStatus, WarehouseStatus newStatus) {
233	        // 같은 상태로의 전환은 허용
234	        if (currentStatus == newStatus) {
235	            return;
236	        }
238	        // 상태별 유효한 전환 확인
239	        switch (currentStatus) {
240	            case IN_STORAGE:
241	                // IN_STORAGE에서는 모든 상태로 전환 가능
242	                break;
243	            case ASSOCIATED_WITH_ORDER:
244	                if (newStatus == WarehouseStatus.IN_STORAGE) {
245	                    throw new InvalidStatusTransitionException(
246	                            "주문과 연결된 상태(ASSOCIATED_WITH_ORDER)에서 보관 상태(IN_STORAGE)로 직접 전환할 수 없습니다.");
247	                }
